const LOGO_B64 = '';

/**
 * deck.js — generador del reporte de avance en el navegador.
 *
 * Port fiel del motor `atxlab_deck.js` + `bloques_avance.js` de las skills
 * atxlab-decks / atxlab-avance. Si cambias el diseño allá, refléjalo aquí.
 * Requiere pptxgenjs cargado como global (PptxGenJS).
 *
 *   DeckAvance.descargar(corte)   -> arma y descarga el .pptx
 */
window.DeckAvance = (function () {

const C = {
  moradoProfundo: '4A1080', moradoMedio: '5A1B96', moradoVivo: '7B2FBE',
  lavanda: 'D4A8F0', lavandaClara: 'C084FC', tinte: 'F8F4FF',
  cuerpo: '555555', tenue: '888888', blanco: 'FFFFFF', verde: '22C55E',
};
const EST = { verde: '22C55E', ambar: 'F59E0B', rojo: 'EF4444' };
const SEM = {
  verde: { color: EST.verde, texto: 'En tiempo' },
  ambar: { color: EST.ambar, texto: 'Con atención' },
  rojo:  { color: EST.rojo,  texto: 'En riesgo' },
};
const FUENTE = 'Calibri';
const G = { W: 13.333, H: 7.5, M: 0.7, ancho: 11.93, yEyebrow: 0.5, yTitulo: 0.85, yPie: 7.08 };
const LOGO = 'data:image/png;base64,' + LOGO_B64;

function pie(pres, s) {
  const num = pres.slides ? pres.slides.length : 1;
  s.addText('atxlab', { x: 0.6, y: G.yPie, w: 2.0, h: 0.3, fontFace: FUENTE, fontSize: 10, bold: true, color: C.tenue, margin: 0 });
  s.addText(String(num), { x: 12.23, y: G.yPie, w: 0.6, h: 0.3, fontFace: FUENTE, fontSize: 10, color: C.tenue, align: 'right', margin: 0 });
}

function tituloMulti(s, titulo, o) {
  const lineas = String(titulo).split('\n');
  s.addText(lineas.map((t, i) => ({ text: t, options: { breakLine: i < lineas.length - 1 } })), o(lineas.length));
  return lineas.length;
}

function slideContenido(pres, { eyebrow, titulo }) {
  const s = pres.addSlide();
  s.background = { color: C.blanco };
  s.addText(String(eyebrow).toUpperCase(), {
    x: G.M, y: G.yEyebrow, w: 8.0, h: 0.4, fontFace: FUENTE, fontSize: 13, bold: true,
    color: C.moradoVivo, charSpacing: 2, margin: 0, valign: 'middle',
  });
  tituloMulti(s, titulo, (n) => ({
    x: G.M, y: G.yTitulo, w: 8.6, h: n > 1 ? 1.5 : 1.1, fontFace: FUENTE, fontSize: 26,
    bold: true, color: C.moradoProfundo, margin: 0, valign: 'middle', lineSpacingMultiple: 1.15,
  }));
  pie(pres, s);
  return s;
}

function portadaAvance(pres, o) {
  const s = pres.addSlide();
  s.background = { color: C.moradoProfundo };
  s.addShape('ellipse', { x: 9.6, y: -2.2, w: 6.0, h: 6.0, fill: { color: C.moradoVivo, transparency: 70 } });
  s.addShape('ellipse', { x: -2.4, y: 4.6, w: 5.0, h: 5.0, fill: { color: C.lavandaClara, transparency: 78 } });
  s.addImage({ data: LOGO, x: 0.45, y: 0.31, w: 2.93, h: 0.77 });
  s.addText('AVANCE DE PROYECTO', {
    x: G.M, y: 2.55, w: 8.0, h: 0.4, fontFace: FUENTE, fontSize: 14, bold: true,
    color: C.lavanda, charSpacing: 3, margin: 0,
  });
  tituloMulti(s, o.titulo, () => ({
    x: G.M, y: 2.95, w: 8.5, h: 1.3, fontFace: FUENTE, fontSize: 44, bold: true,
    color: C.blanco, margin: 0, valign: 'middle',
  }));
  s.addText(o.subtitulo, { x: G.M, y: 4.15, w: 9.5, h: 0.8, fontFace: FUENTE, fontSize: 18, color: C.lavanda, margin: 0 });

  const sem = SEM[o.semaforo] || SEM.verde, x = 9.35, y = 2.55, w = 3.28, h = 0.62;
  s.addShape('roundRect', { x, y, w, h, rectRadius: 0.31, fill: { color: C.blanco, transparency: 88 }, line: { color: sem.color, width: 1.25 } });
  s.addShape('ellipse', { x: x + 0.28, y: y + 0.21, w: 0.2, h: 0.2, fill: { color: sem.color } });
  s.addText(sem.texto, { x: x + 0.58, y, w: w - 0.75, h, fontFace: FUENTE, fontSize: 14, bold: true, color: C.blanco, valign: 'middle', margin: 0 });
  if (o.periodo) s.addText(o.periodo, { x, y: y + h + 0.12, w, h: 0.35, fontFace: FUENTE, fontSize: 12, color: C.lavanda, margin: 0 });

  s.addShape('line', { x: G.M, y: 6.35, w: 4.2, h: 0, line: { color: C.moradoVivo, width: 1 } });
  if (o.preparadoPara) s.addText(o.preparadoPara, { x: G.M, y: 6.45, w: 6.0, h: 0.35, fontFace: FUENTE, fontSize: 13, color: C.blanco, margin: 0 });
  if (o.contacto) s.addText(o.contacto, { x: G.M, y: 6.78, w: 8.0, h: 0.35, fontFace: FUENTE, fontSize: 12, color: C.lavanda, margin: 0 });
  return s;
}

function cierre(pres, { eyebrow, titulo, pasos = [], contacto = [] }) {
  const s = pres.addSlide();
  s.background = { color: C.moradoProfundo };
  s.addShape('ellipse', { x: 9.8, y: -2.0, w: 5.5, h: 5.5, fill: { color: C.moradoVivo, transparency: 70 } });
  s.addText(String(eyebrow).toUpperCase(), { x: G.M, y: G.yEyebrow, w: 8.0, h: 0.4, fontFace: FUENTE, fontSize: 13, bold: true, color: C.lavanda, charSpacing: 2, margin: 0 });
  tituloMulti(s, titulo, () => ({ x: G.M, y: G.yTitulo, w: 8.6, h: 1.5, fontFace: FUENTE, fontSize: 30, bold: true, color: C.blanco, margin: 0, valign: 'middle', lineSpacingMultiple: 1.15 }));
  let y = 3.3;
  pasos.forEach((t, i) => {
    s.addShape('ellipse', { x: G.M, y, w: 0.5, h: 0.5, fill: { color: C.moradoVivo } });
    s.addText(String(i + 1), { x: G.M, y, w: 0.5, h: 0.5, fontFace: FUENTE, fontSize: 14, bold: true, color: C.blanco, align: 'center', valign: 'middle', margin: 0 });
    s.addText(t, { x: 1.4, y: y - 0.05, w: 7.2, h: 0.65, fontFace: FUENTE, fontSize: 13.5, color: C.blanco, valign: 'middle', margin: 0 });
    y += 0.85;
  });
  s.addShape('line', { x: G.M, y: 6.15, w: 4.2, h: 0, line: { color: C.moradoVivo, width: 1 } });
  if (contacto[0]) s.addText(contacto[0], { x: G.M, y: 6.30, w: 6.0, h: 0.35, fontFace: FUENTE, fontSize: 13, color: C.blanco, margin: 0 });
  if (contacto[1]) s.addText(contacto[1], { x: G.M, y: 6.65, w: 6.0, h: 0.35, fontFace: FUENTE, fontSize: 12, color: C.lavanda, margin: 0 });
  s.addImage({ data: LOGO, x: 10.6, y: 6.45, w: 1.9, h: 0.5 });
  return s;
}

function avanceGlobal(s, { real, plan, y }) {
  const r = Math.max(0, Math.min(100, Math.round(real)));
  const p = Math.max(0, Math.min(100, Math.round(plan)));
  s.addText(r + '%', { x: G.M, y, w: 2.7, h: 1.2, fontFace: FUENTE, fontSize: 54, bold: true, color: C.moradoProfundo, valign: 'middle', margin: 0 });
  s.addText('de avance real', { x: G.M, y: y + 1.12, w: 2.7, h: 0.4, fontFace: FUENTE, fontSize: 13, color: C.cuerpo, margin: 0 });
  const bx = 3.6, bw = 9.03, bh = 0.46, by = y + 0.38;
  s.addShape('roundRect', { x: bx, y: by, w: bw, h: bh, rectRadius: 0.23, fill: { color: C.tinte }, line: { color: C.lavanda, width: 1 } });
  if (r > 0) s.addShape('roundRect', { x: bx, y: by, w: Math.max(bw * r / 100, 0.46), h: bh, rectRadius: 0.23, fill: { color: C.moradoVivo }, line: { color: C.moradoVivo, width: 1 } });
  const px = bx + bw * p / 100;
  s.addShape('line', { x: px, y: by - 0.16, w: 0, h: bh + 0.32, line: { color: C.moradoProfundo, width: 1.75, dashType: 'dash' } });
  s.addText('Plan a la fecha  ' + p + '%', { x: Math.min(px - 1.1, bx + bw - 2.2), y: by + bh + 0.18, w: 2.2, h: 0.3, fontFace: FUENTE, fontSize: 11.5, color: C.tenue, align: 'center', margin: 0 });
  const d = r - p, col = d >= -3 ? EST.verde : (d >= -10 ? EST.ambar : EST.rojo);
  const txt = d === 0 ? 'En línea con el plan' : (d > 0 ? d + ' puntos adelante del plan' : Math.abs(d) + ' puntos abajo del plan');
  s.addShape('roundRect', { x: bx, y: by - 0.72, w: 3.5, h: 0.42, rectRadius: 0.21, fill: { color: C.blanco }, line: { color: col, width: 1.25 } });
  s.addShape('ellipse', { x: bx + 0.22, y: by - 0.6, w: 0.18, h: 0.18, fill: { color: col } });
  s.addText(txt, { x: bx + 0.48, y: by - 0.72, w: 3.0, h: 0.42, fontFace: FUENTE, fontSize: 11.5, bold: true, color: C.moradoProfundo, valign: 'middle', margin: 0 });
}

function lineaHitos(s, hitos, { y }) {
  s.addText('Hitos del proyecto', { x: G.M, y: y - 0.55, w: 6.0, h: 0.35, fontFace: FUENTE, fontSize: 13, bold: true, color: C.moradoProfundo, margin: 0 });
  const n = hitos.length, paso = G.ancho / n, cy = y + 0.42;
  s.addShape('line', { x: G.M + paso / 2, y: cy, w: G.ancho - paso, h: 0, line: { color: C.lavanda, width: 1.5 } });
  hitos.forEach((h, i) => {
    const cx = G.M + paso * i + paso / 2;
    const ok = h.estado === 'cumplido', cur = h.estado === 'encurso', d = cur ? 0.42 : 0.34;
    s.addShape('ellipse', { x: cx - d / 2, y: cy - d / 2, w: d, h: d,
      fill: { color: ok ? C.moradoProfundo : (cur ? C.blanco : C.tinte) },
      line: { color: ok ? C.moradoProfundo : (cur ? C.moradoVivo : C.lavanda), width: cur ? 2.5 : 1.25 } });
    if (ok) s.addText('✓', { x: cx - d / 2, y: cy - d / 2, w: d, h: d, fontFace: FUENTE, fontSize: 12, bold: true, color: C.blanco, align: 'center', valign: 'middle', margin: 0 });
    s.addText(h.semana || '', { x: cx - paso / 2, y: cy - 0.62, w: paso, h: 0.3, fontFace: FUENTE, fontSize: 11, bold: true, color: ok || cur ? C.moradoVivo : C.tenue, align: 'center', margin: 0 });
    s.addText(h.nombre, { x: cx - paso / 2 + 0.08, y: cy + 0.3, w: paso - 0.16, h: 0.6, fontFace: FUENTE, fontSize: 11.5, bold: cur, color: ok || cur ? C.moradoProfundo : C.tenue, align: 'center', valign: 'top', margin: 0, lineSpacingMultiple: 1.1 });
  });
}

function frentesTrabajo(s, frentes, { y }) {
  const n = frentes.length, gap = 0.35, w = (G.ancho - gap * (n - 1)) / n;
  const hayDet = frentes.some((f) => (f.detenidas || []).length);
  const maxF = Math.max.apply(null, frentes.map((f) => (f.cerradas || []).length + (f.enCurso || []).length + (f.detenidas || []).length));
  const h = Math.min(1.18 + maxF * 0.54, 4.3);
  frentes.forEach((f, i) => {
    const x = G.M + i * (w + gap);
    s.addShape('roundRect', { x, y, w, h, rectRadius: 0.12, fill: { color: C.tinte }, line: { color: C.lavanda, width: 1 } });
    s.addShape('ellipse', { x: x + 0.32, y: y + 0.28, w: 0.55, h: 0.55, fill: { color: C.blanco }, line: { color: C.lavanda, width: 1 } });
    s.addText(f.icono || '⚙️', { x: x + 0.32, y: y + 0.28, w: 0.55, h: 0.55, fontFace: FUENTE, fontSize: 20, align: 'center', valign: 'middle', margin: 0 });
    s.addText(f.titulo, { x: x + 1.02, y: y + 0.22, w: w - 1.35, h: 0.5, fontFace: FUENTE, fontSize: 15, bold: true, color: C.moradoProfundo, valign: 'middle', margin: 0 });
    const filas = [];
    (f.cerradas || []).forEach((t) => filas.push({ e: 'ok', t }));
    (f.enCurso || []).forEach((t) => filas.push({ e: 'curso', t }));
    (f.detenidas || []).forEach((t) => filas.push({ e: 'stop', t }));
    let yy = y + 1.02;
    filas.forEach((r) => {
      if (r.e === 'ok') {
        s.addText('✓', { x: x + 0.34, y: yy, w: 0.3, h: 0.34, fontFace: FUENTE, fontSize: 13, bold: true, color: C.verde, align: 'center', valign: 'middle', margin: 0 });
      } else {
        const col = r.e === 'stop' ? EST.ambar : C.moradoVivo;
        s.addShape('ellipse', { x: x + 0.42, y: yy + 0.09, w: 0.16, h: 0.16, fill: { color: r.e === 'stop' ? EST.ambar : C.blanco }, line: { color: col, width: 2 } });
      }
      s.addText(r.t, { x: x + 0.72, y: yy, w: w - 1.05, h: 0.5, fontFace: FUENTE, fontSize: 12, color: r.e === 'ok' ? C.cuerpo : C.moradoProfundo, bold: r.e !== 'ok', valign: 'top', margin: 0, lineSpacingMultiple: 1.1 });
      yy += 0.54;
    });
  });
  const ly = y + h + 0.22;
  s.addText('✓', { x: G.M, y: ly, w: 0.25, h: 0.3, fontFace: FUENTE, fontSize: 12, bold: true, color: C.verde, align: 'center', valign: 'middle', margin: 0 });
  s.addText('Cerrado en esta quincena', { x: G.M + 0.3, y: ly, w: 2.6, h: 0.3, fontFace: FUENTE, fontSize: 11.5, color: C.tenue, valign: 'middle', margin: 0 });
  s.addShape('ellipse', { x: G.M + 3.05, y: ly + 0.07, w: 0.16, h: 0.16, fill: { color: C.blanco }, line: { color: C.moradoVivo, width: 2 } });
  s.addText('En curso', { x: G.M + 3.35, y: ly, w: 1.3, h: 0.3, fontFace: FUENTE, fontSize: 11.5, color: C.tenue, valign: 'middle', margin: 0 });
  if (hayDet) {
    s.addShape('ellipse', { x: G.M + 4.75, y: ly + 0.07, w: 0.16, h: 0.16, fill: { color: EST.ambar }, line: { color: EST.ambar, width: 2 } });
    s.addText('Detenido por un pendiente', { x: G.M + 5.05, y: ly, w: 2.8, h: 0.3, fontFace: FUENTE, fontSize: 11.5, color: C.tenue, valign: 'middle', margin: 0 });
  }
}

function columnasEstado(s, { izquierda, derecha, y, altoTarjeta = 1.28, gap = 0.16 }) {
  const anchoT = 5.75, xs = [G.M, 6.85];
  [izquierda, derecha].forEach((col, ci) => {
    if (!col) return;
    const x = xs[ci];
    s.addText((col.icono ? col.icono + '  ' : '') + col.titulo, { x, y: y - 0.5, w: anchoT, h: 0.4, fontFace: FUENTE, fontSize: 14.5, bold: true, color: C.moradoProfundo, margin: 0 });
    const items = col.items || [];
    if (!items.length) {
      s.addShape('roundRect', { x, y, w: anchoT, h: 1.0, rectRadius: 0.12, fill: { color: C.tinte }, line: { color: C.lavanda, width: 1 } });
      s.addText(col.vacio || 'Sin puntos abiertos en este periodo.', { x: x + 0.35, y, w: anchoT - 0.7, h: 1.0, fontFace: FUENTE, fontSize: 12.5, color: C.cuerpo, valign: 'middle', margin: 0 });
      return;
    }
    items.forEach((it, i) => {
      const yy = y + i * (altoTarjeta + gap);
      const acento = EST[it.tono] || C.moradoVivo;
      s.addShape('roundRect', { x, y: yy, w: anchoT, h: altoTarjeta, rectRadius: 0.12, fill: { color: C.tinte }, line: { color: C.lavanda, width: 1 } });
      s.addShape('roundRect', { x: x + 0.14, y: yy + 0.18, w: 0.09, h: altoTarjeta - 0.36, rectRadius: 0.045, fill: { color: acento }, line: { color: acento, width: 0.5 } });
      s.addText(it.titulo, { x: x + 0.42, y: yy + 0.14, w: anchoT - 0.72, h: 0.34, fontFace: FUENTE, fontSize: 13, bold: true, color: C.moradoProfundo, valign: 'middle', margin: 0 });
      if (it.detalle) s.addText(it.detalle, { x: x + 0.42, y: yy + 0.46, w: anchoT - 0.72, h: 0.42, fontFace: FUENTE, fontSize: 11.5, color: C.cuerpo, margin: 0, lineSpacingMultiple: 1.1 });
      if (it.meta) s.addText(it.meta, { x: x + 0.42, y: yy + altoTarjeta - 0.42, w: anchoT - 0.72, h: 0.32, fontFace: FUENTE, fontSize: 11, bold: true, color: acento === C.moradoVivo ? C.moradoVivo : acento, valign: 'middle', margin: 0 });
    });
  });
}

/* ── Armado del deck a partir del corte ─────────────────────────────── */
function construir(k) {
  const pres = new PptxGenJS();
  pres.layout = 'LAYOUT_WIDE';
  pres.theme = { headFontFace: FUENTE, bodyFontFace: FUENTE };

  portadaAvance(pres, {
    titulo: k.proyecto,
    subtitulo: 'Reporte de avance · Semana ' + k.semana + ' de ' + k.semanasTotales,
    periodo: k.periodo, semaforo: k.semaforo,
    preparadoPara: 'Preparado para ' + k.contactoCliente + ' · ' + k.cliente,
    contacto: k.contactoAtx,
  });

  let s = slideContenido(pres, { eyebrow: 'Dónde vamos', titulo: k.tituloAvance });
  avanceGlobal(s, { real: k.avanceReal, plan: k.avancePlan, y: 2.95 });
  if (k.hitos && k.hitos.length) lineaHitos(s, k.hitos, { y: 5.35 });

  s = slideContenido(pres, { eyebrow: 'En qué estamos', titulo: k.tituloActividades });
  frentesTrabajo(s, k.frentes, { y: 2.5 });

  s = slideContenido(pres, { eyebrow: 'Qué necesitamos', titulo: k.tituloPendientes });
  columnasEstado(s, {
    y: 2.55,
    izquierda: { icono: '⚠️', titulo: 'Lo que nos está frenando', items: k.trabas,
                 vacio: 'Sin trabas abiertas en este periodo.' },
    derecha:   { icono: '📋', titulo: 'Pendientes del lado de ' + k.cliente, items: k.pendientes,
                 vacio: 'Sin pendientes abiertos en este periodo.' },
  });

  cierre(pres, {
    eyebrow: 'Próximas 2 semanas', titulo: k.tituloSigue,
    pasos: k.pasos,
    contacto: ['Próxima sesión de avance: ' + k.proximaSesion, k.contactoCierre],
  });
  return pres;
}

function descargar(k) {
  const pres = construir(k);
  return pres.writeFile({ fileName: k.archivo });
}

return { construir, descargar, C, EST };
})();
